(function(){
'use strict';
const Engine=window.MiyarCompensation;if(!Engine)return;
const KEY='miyar-compensation-scenarios-v1';
const workspace=window.MiyarScenarioWorkspace.create({prefix:'cp',key:KEY,schema:'miyar-compensation-scenario/1.0',calculate:Engine.evaluate,values,fill,renderResult:result,bindResult:bind,resultAttribute:'result',fromInput:i=>({...i,targetPenetration:i.targetPenetrationPercent})});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ar(){return document.documentElement.lang!=='en';}function t(a,b){return ar()?a:b;}function money(v,c){return Number(v).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:2})+' '+esc(c);}
function read(){return workspace.rows();}
function save(v){return workspace.save(v);}
function field(id,label,value='',attrs='',hint=''){return '<label class="cp-field">'+label+'<input id="cp-'+id+'" value="'+esc(value)+'" '+attrs+(hint?' aria-describedby="cp-'+id+'-hint"':'')+'>'+(hint?'<small id="cp-'+id+'-hint" class="cp-hint">'+hint+'</small>':'')+'</label>';}
function pct(v,d=1){if(v===null||!Number.isFinite(Number(v)))return '—';return Number(v).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:d})+'%';}
function values(){return {payBasis:document.getElementById('cp-basis').value,role:document.getElementById('cp-role').value,grade:document.getElementById('cp-grade').value,headcount:document.getElementById('cp-headcount').value,currency:document.getElementById('cp-currency').value,period:document.getElementById('cp-period').value,bandSource:document.getElementById('cp-source').value,bandMin:document.getElementById('cp-min').value,bandMid:document.getElementById('cp-mid').value,bandMax:document.getElementById('cp-max').value,targetPenetration:document.getElementById('cp-target').value,currentSalary:document.getElementById('cp-current').value,oncostPercent:document.getElementById('cp-oncost').value,allowancesPercent:document.getElementById('cp-allowances')?.value??''};}
function fill(e){for(const [k,v] of Object.entries({role:e.role,grade:e.grade,headcount:e.headcount,currency:e.currency,source:e.bandSource,min:e.bandMin,mid:e.bandMid,max:e.bandMax,target:e.targetPenetration,current:e.currentSalary,oncost:e.oncostPercent,allowances:e.allowancesPercent})){const el=document.getElementById('cp-'+k);if(el)el.value=v??'';}document.getElementById('cp-period').value=e.period||'monthly';document.getElementById('cp-basis').value=e.payBasis||'basic';}
function gradeFromInstitution(role){const I=window.MiyarInstitutionProfile,p=I?.read?.();if(!I||!p||!String(role||'').trim())return'';const g=I.matchGrade(p,role);return g?g.id+' · '+(ar()?g.labelAr:g.labelEn):'';}
const zoneNames={'well-below':['أقل بكثير من المنتصف','Well below midpoint'],below:['دون المنتصف — مرحلة تطور','Below midpoint — developing'],at:['عند المنتصف — أداء كامل','At midpoint — fully proficient'],above:['فوق المنتصف','Above midpoint'],'well-above':['أعلى بكثير من المنتصف','Well above midpoint']};
const quartileNames={Q1:['الربع الأول من النطاق','First range quartile'],Q2:['الربع الثاني من النطاق','Second range quartile'],Q3:['الربع الثالث من النطاق','Third range quartile'],Q4:['الربع الرابع من النطاق','Fourth range quartile'],'below-minimum':['دون الحد الأدنى','Below minimum'],'above-maximum':['فوق الحد الأعلى','Above maximum']};
function guidance(v){const r=v.result,i=v.input,c=i.currency;
 if(r.payAction==='new-position')return [t('منصب جديد — العرض عند الهدف','New position — offer at target'),t('ثبّت العرض عند '+money(r.targetSalary,c)+' ('+pct(i.targetPenetrationPercent)+' من النطاق). العرض فوق المنتصف يحتاج مبررًا موثقًا مثل ندرة المهارة أو الخبرة.','Anchor the offer at '+money(r.targetSalary,c)+' ('+pct(i.targetPenetrationPercent)+' of range). Offers above the midpoint need a documented reason such as skill scarcity or experience.')];
 if(r.payAction==='increase')return [t('اقتراح تعويض للمراجعة','Compensation proposal for review'),t('زيادة '+money(r.adjustmentPerFte,c)+' لكل FTE ('+pct(r.adjustmentPercent)+') للوصول إلى الهدف.','An increase of '+money(r.adjustmentPerFte,c)+' per FTE ('+pct(r.adjustmentPercent)+') reaches the target.')+(r.adjustmentPercent>15?t(' تعديل كبير: فكّر في جدولته على أكثر من دورة مراجعة.',' Large adjustment: consider phasing it across review cycles.'):'')];
 if(r.payAction==='hold')return [t('تثبيت الراتب — لا تخفيض تلقائي','Hold salary — no automatic reduction'),t('الراتب عند الهدف أو أعلى؛ لا تعديل بسبب الموضع. زيادة الأداء تتبع سياسة الجهة.','Pay is at or above target; no positioning adjustment. Merit increases follow the organization policy.')];
 if(r.payAction==='below-band')return [t('أقل من النطاق — يحتاج مراجعة','Below band — review required'),t('الممارسة الشائعة: رفع الراتب إلى الحد الأدنى على الأقل ('+money(r.minimumAdjustmentPerFte,c)+' لكل FTE؛ الأثر السنوي '+money(r.annualMinimumAdjustmentCost,c)+'). يمكن جدولة الانتقال إلى الهدف.','Common practice: bring pay to at least the band minimum ('+money(r.minimumAdjustmentPerFte,c)+' per FTE; annual impact '+money(r.annualMinimumAdjustmentCost,c)+'). The move to target can be phased.')];
 return [t('أعلى من النطاق — تثبيت للمراجعة','Above band — red-circle / hold for review'),t('لا تخفيض. أوقف زيادات الراتب الأساسي حتى يلحق النطاق، واستخدم مكافآت مقطوعة غير مضافة للأساس عند الأداء المتميز.','No reduction. Pause base increases until the band catches up and use non-consolidated lump sums for strong performance.')];}
function rangeBar(v){const i=v.input,r=v.result,pos=r.currentRangePenetrationPercent,clamp=n=>Math.max(0,Math.min(100,n));return '<div class="cp-range" dir="ltr"><div class="cp-line"><span style="left:0%"></span><span style="left:25%"></span><span style="left:50%"></span><span style="left:75%"></span><span style="left:100%"></span><i class="cp-target" style="left:'+i.targetPenetrationPercent+'%" title="'+t('الهدف','Target')+'"></i>'+(pos===null?'':'<i class="cp-current" style="left:'+clamp(pos)+'%" title="'+t('الراتب الحالي','Current salary')+'"></i>')+'</div><div class="cp-scale"><span>'+t('الحد الأدنى','Min')+'</span><span>'+t('الربع 1','Q1')+'</span><span>'+t('المنتصف','Mid')+'</span><span>'+t('الربع 3','Q3')+'</span><span>'+t('الحد الأعلى','Max')+'</span></div><div class="cp-legend" dir="auto"><span><i class="cp-target"></i>'+t('الهدف','Target')+'</span>'+(pos===null?'':'<span><i class="cp-current"></i>'+t('الراتب الحالي','Current salary')+'</span>')+'</div></div>';}
function diagnosticsView(v){const d=v.bandDiagnostics,spread={undefined:['غير قابل للحساب عندما يكون الحد الأدنى صفرًا','Not computable when the minimum is zero'],narrow:['ضيق — مساحة تقدم محدودة داخل الدرجة','Narrow — limited progression room within the grade'],common:['ضمن المدى الشائع','Within the common range'],wide:['واسع — فكّر في مناطق داخل النطاق أو تقسيم الدرجة','Wide — consider zones within the band or splitting the grade']}[d.spreadAssessment];return '<div class="cp-diagnostics"><strong>'+t('فحص تصميم النطاق','Band design check')+'</strong><ul><li class="'+(d.spreadAssessment==='common'?'ok':'warn')+'">'+t('اتساع النطاق ','Range spread ')+pct(d.rangeSpreadPercent)+' · '+t(...spread)+'</li><li class="'+(d.midpointCentred?'ok':'warn')+'">'+(d.midpointCentred?t('المنتصف في وسط النطاق','Midpoint is centred in the band'):t('المنتصف منحرف '+pct(d.midpointOffsetPercent)+' عن الوسط — تحقق من البيانات','Midpoint is offset '+pct(d.midpointOffsetPercent)+' from the centre — check the data'))+'</li></ul><small>'+t('مرجع تصميم شائع للاتساع: 20–75% حسب المستوى الوظيفي؛ سياسة التعويضات لدى الجهة هي المرجع.','Common design reference for spread: 20–75% depending on job level; the organization’s Total Rewards policy governs.')+'</small></div>';}
function costView(v){const r=v.result,i=v.input,c=i.currency;if(!i.allowancesApplied)return '';return '<div class="cp-cost"><strong>'+t('تكلفة الحزمة السنوية','Annual package cost')+'</strong><dl><dt>'+t('الراتب الأساسي','Basic pay')+'</dt><dd>'+money(r.annualBasePayroll,c)+'</dd><dt>'+t('البدلات الثابتة','Fixed allowances')+' ('+pct(i.allowancesPercent)+')</dt><dd>'+money(r.annualGuaranteedCash-r.annualBasePayroll,c)+'</dd><dt>'+t('الأجر النقدي المضمون','Guaranteed cash')+'</dt><dd>'+money(r.annualGuaranteedCash,c)+'</dd><dt>'+t('تكلفة صاحب العمل الإضافية','Employer on-cost')+' ('+pct(i.oncostPercent)+')</dt><dd>'+money(r.annualEmployerCost-r.annualGuaranteedCash,c)+'</dd></dl></div>';}
function result(v){const r=v.result,i=v.input,c=i.currency,period=t(i.period==='monthly'?'شهري':'سنوي',i.period==='monthly'?'Monthly':'Annual'),g=guidance(v);return '<section class="cp-result"><div class="cp-result-head"><div><span>'+t('المرحلة 3 · نطاق الجهة','PHASE 3 · ORGANIZATION BAND')+'</span><h2>'+esc(i.role||t('سيناريو التعويض','Compensation scenario'))+'</h2><p>'+esc(i.grade||t('الدرجة غير محددة','Grade not specified'))+' · '+period+'</p></div><strong>'+money(r.recommendedSalary??r.targetSalary,c)+'</strong></div><div class="decision-summary"><strong>'+t('ماذا يعني هذا لقرارك؟','What this means for your decision')+'</strong><p>'+esc(g[0]+' — '+g[1]+' '+t('التكلفة السنوية على صاحب العمل: ','Annual employer cost: ')+Number(r.annualEmployerCost).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:0})+' '+c+'.')+'</p></div><div class="cp-metrics"><div><span>'+t('الحد الأدنى','Minimum')+'</span><b>'+money(i.bandMin,c)+'</b></div><div><span>'+t('المنتصف','Midpoint')+'</span><b>'+money(i.bandMid,c)+'</b></div><div><span>'+t('الحد الأعلى','Maximum')+'</span><b>'+money(i.bandMax,c)+'</b></div><div><span>'+t('موضع الهدف داخل النطاق','Target range position')+'</span><b>'+pct(i.targetPenetrationPercent)+'</b></div><div><span>'+t('نسبة المقارنة بالمنتصف (Compa-ratio)','Compa-ratio')+'</span><b>'+(r.compaRatio===null?'—':Number(r.compaRatio).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:3}))+'</b>'+(r.compaZone?'<small>'+t(...zoneNames[r.compaZone])+(r.currentQuartile?' · '+t(...quartileNames[r.currentQuartile]):'')+'</small>':'')+'</div><div><span>'+t('إجمالي تكلفة صاحب العمل سنويًا','Annual employer cost')+'</span><b>'+money(r.annualEmployerCost,c)+'</b></div></div>'+rangeBar(v)+(r.adjustmentPerFte===null?'<p class="cp-note">'+t('لم يُدخل راتب حالي/مرجعي؛ لذلك تبقى نسبة Compa-ratio وتكلفة التعديل غير معروفتين بدل عرض صفر.','No current/reference salary was provided, so compa-ratio and adjustment cost remain unknown rather than displaying zero.')+'</p>':'<div class="cp-adjust"><strong>'+t('الفرق لكل FTE','Difference per FTE')+': '+money(r.adjustmentPerFte,c)+'</strong><span>'+t('الأثر السنوي شامل تكلفة صاحب العمل','Annual adjustment including employer on-cost')+': '+money(r.annualAdjustmentCost,c)+'</span></div>')+'<div class="cp-policy"><strong>'+g[0]+'</strong><p>'+esc(g[1])+'</p><p class="cp-basis">'+t('أساس الحساب: '+(i.payBasis==='total'?'الأجر الإجمالي':'الأجر الأساسي')+'. نسبة تكلفة صاحب العمل مدخلة يدويًا؛ لا يحسب النظام اشتراكات GOSI تلقائيًا.','Pay basis: '+(i.payBasis==='total'?'total cash pay':'basic salary')+'. Employer on-cost is entered manually; GOSI contributions are not calculated automatically.')+(i.payBasis==='total'&&i.allowancesPercent?t(' البدلات مشمولة في الأجر الإجمالي ولم تُضف مرة أخرى.',' Allowances are already inside total cash pay and were not added again.'):'')+'</p></div>'+costView(v)+diagnosticsView(v)+'<div class="cp-warning"><strong>'+t('ليس Benchmark سوقي','Not a market benchmark')+'</strong><p>'+esc(t('الحساب يستخدم فقط نطاق الراتب الذي أدخلته الجهة ومصدره. الربعان Q1 وQ3 مواضع داخل نطاق الجهة وليست مئينات سوقية. لا يستنتج عدالة الأجر ولا قيمة السوق ولا يصدر اعتماد تعويضات.','The calculation uses only the organization-provided salary band and source. Q1 and Q3 are positions inside the organization band, not market percentiles. It does not infer pay equity, market value or compensation approval.'))+'</p></div><div class="action-row"><button type="button" class="button button-primary" data-cp-save>'+t('حفظ السيناريو','Save scenario')+'</button><button type="button" class="button button-outline" data-cp-export>'+t('تصدير JSON','Export JSON')+'</button></div><p data-cp-status role="status"></p></section>';}
function bind(v){const root=document.querySelector('.cp-result');root.querySelector('[data-cp-save]').onclick=()=>{try{const r=save(v);root.querySelector('[data-cp-status]').textContent=t('حُفظ السيناريو: ','Scenario saved: ')+r.id;}catch(e){workspace.fail(e);}};root.querySelector('[data-cp-export]').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(v,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='miyar-compensation-scenario.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);};}
function render(){if(location.hash!=='#enterprise/compensation')return;const content=document.getElementById('ent-content');if(!content)return;document.getElementById('enterprise-heading').textContent=t('التعويضات','Compensation');const bc=document.getElementById('breadcrumb-title');if(bc)bc.textContent=t('التعويضات','Compensation');document.querySelectorAll('.nav-link').forEach(x=>x.classList.remove('active'));document.querySelector('[data-comp-nav]')?.classList.add('active');let pending=null;try{pending=JSON.parse(sessionStorage.getItem('miyar-compensation-handoff')||'null');}catch{}content.innerHTML='<section class="cp-page"><div class="cp-heading"><div><span>'+t('المرحلة 3 · التعويضات','PHASE 3 · COMPENSATION')+'</span><h2>'+t('اربط الدرجة بنطاق التعويض المعتمد لدى الجهة','Link the grade to the organization-approved compensation band')+'</h2><p>'+t('معيار لا يخترع رواتب سوقية. أدخل نطاق الجهة ومصدره، ثم احسب موضع الراتب والأثر على التكلفة بشكل قابل للمراجعة.','Miyar does not invent market salaries. Enter the organization band and its source, then calculate salary positioning and cost impact transparently.')+'</p></div><button type="button" class="button button-outline" data-cp-example>'+t('تحميل مثال توضيحي','Load illustrative example')+'</button></div><div class="cp-form">'+field('role',t('الدور / المنصب','Role / position'),pending?.role||'')+field('grade',t('الدرجة','Grade'),pending?.grade||gradeFromInstitution(pending?.role||''))+field('headcount',t('عدد FTE','Headcount'),pending?.headcount||1,'type="number" min="1" step="1"')+field('currency',t('العملة','Currency'),'SAR','maxlength="3"')+'<label class="cp-field">'+t('فترة النطاق','Band period')+'<select id="cp-period"><option value="monthly">'+t('شهري','Monthly')+'</option><option value="annual">'+t('سنوي','Annual')+'</option></select></label>'+'<label class="cp-field">'+t('أساس النطاق والراتب','Band and salary basis')+'<select id="cp-basis"><option value="basic">'+t('الراتب الأساسي','Basic salary')+'</option><option value="total">'+t('إجمالي الأجر النقدي','Total cash pay')+'</option></select></label>'+field('source',t('مصدر نطاق الراتب / مرجع الجهة','Salary-band source / organization reference'),'')+field('min',t('الحد الأدنى','Minimum'),'','type="number" min="0" step="any"')+field('mid',t('المنتصف','Midpoint'),'','type="number" min="0" step="any"')+field('max',t('الحد الأعلى','Maximum'),'','type="number" min="0" step="any"')+field('target',t('موضع الهدف داخل النطاق %','Target range position %'),'50','type="number" min="0" max="100" step="1"')+field('current',t('راتب حالي/مرجعي — اختياري','Current/reference salary — optional'),'','type="number" min="0" step="any"')+field('oncost',t('تكلفة صاحب العمل الإضافية %','Employer on-cost %'),'0','type="number" min="0" max="200" step="0.1"',t('حصة صاحب العمل في التأمينات، التأمين الطبي، مخصص نهاية الخدمة ومزايا أخرى — حسب سياسة الجهة.','Employer social-insurance share, medical insurance, end-of-service accrual and other benefits — per organization policy.'))+field('allowances',t('البدلات الثابتة % من الأساسي — اختياري','Fixed allowances % of basic — optional'),'','type="number" min="0" max="200" step="0.1"',t('مثل السكن والنقل حسب سياسة الجهة؛ تُتجاهل إذا كان النطاق على إجمالي الأجر.','For example housing and transport per organization policy; ignored when the band is on total cash pay.'))+'</div><div class="cp-run"><button type="button" class="button button-primary" data-cp-run>'+t('احسب موضع التعويض','Calculate compensation position')+'</button><span data-cp-message role="status">'+t('يجب أن يكون النطاق من مصدر داخلي معتمد أو مبرر موثق.','The band must come from an approved internal source or documented rationale.')+'</span></div><div data-cp-result></div></section>';sessionStorage.removeItem('miyar-compensation-handoff');content.querySelector('[data-cp-example]').onclick=()=>workspace.example(Engine.example);content.querySelector('[data-cp-run]').onclick=()=>workspace.calculate();if(pending)workspace.example({...pending,period:'monthly',currency:'SAR',targetPenetration:50,oncostPercent:0});workspace.mount(content);}

function ensureNav(){const nav=document.querySelector('.sidebar nav.nav-list');if(!nav)return;let link=nav.querySelector('[data-comp-nav]');if(!link){link=document.createElement('a');link.href='#enterprise/compensation';link.className='nav-link';link.dataset.compNav='true';link.innerHTML='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16v12H4zM7 4h10v3M8 12h8m-4-3v6"/></svg><span>'+t('التعويضات','Compensation')+'</span>';const mp=nav.querySelector('[data-manpower-nav]'),grade=nav.querySelector('[data-enterprise-open="grading"]');(mp||grade)?.after(link);}else link.querySelector('span').textContent=t('التعويضات','Compensation');}
function injectManpowerLink(){if(location.hash!=='#enterprise/manpower')return;const actions=document.querySelector('.mp-results .action-row'),plan=window.MiyarManpowerWorkbench?.getResult?.();if(!actions||actions.querySelector('[data-cp-from-mp]')||!plan||plan.scenarios.base.final.rawGapFte<=.5)return;const btn=document.createElement('button');btn.type='button';btn.className='button button-outline';btn.dataset.cpFromMp='true';btn.textContent=t('احسب أثر التعويض','Estimate compensation impact');actions.append(btn);btn.onclick=()=>{const current=window.MiyarManpowerWorkbench.getResult();if(!current||current.scenarios.base.final.rawGapFte<=.5)return;sessionStorage.setItem('miyar-compensation-handoff',JSON.stringify({role:current.input.role,grade:gradeFromInstitution(current.input.role),headcount:current.scenarios.base.final.gapHeadcount}));location.hash='#enterprise/compensation';};}
window.addEventListener('miyar:scenario-result',e=>{if(e.detail.prefix==='mp')injectManpowerLink();});
window.addEventListener('hashchange',()=>setTimeout(()=>{ensureNav();render();injectManpowerLink();},0));window.addEventListener('miyar:navigate',()=>setTimeout(()=>{ensureNav();render();injectManpowerLink();},0));document.addEventListener('click',e=>{const link=e.target.closest('[data-comp-nav]');if(link){e.preventDefault();location.hash='#enterprise/compensation';setTimeout(render,0);}if(e.target.closest('[data-mp-run]'))setTimeout(injectManpowerLink,0);});setTimeout(()=>{ensureNav();render();injectManpowerLink();},0);window.MiyarCompensationWorkbench={KEY,read,render};
})();
